def put_owned(path, data):
    path.parent.mkdir(parents=True,exist_ok=True)
    if path.exists():
        if path.read_bytes()!=data:
            raise SystemExit('Preserving differing local file: '+str(path))
    else:
        path.write_bytes(data)

for resource in CFG['resources']:
