        data=path.read_bytes()
    else:
        with urllib.request.urlopen(resource['url'],timeout=60) as response:
            data=response.read()
    if hashlib.sha256(data).hexdigest()!=resource['sha256']:
        raise SystemExit('Source SHA256 mismatch: '+resource['path'])
    put_owned(path,data)

